package com.example.blades360;

import android.content.*;
import android.graphics.*;
import android.view.*;
import org.json.*;
import java.util.*;

/** Full Marketplace page: orange content, silver curved rails, category list and feature panel. */
final class RommMarketplace extends View {
  final MainActivity a;final RommClient ra;final Paint p=new Paint(3);final ArrayList<Item> rows=new ArrayList<>();
  int screen,index,offset;float scale=1,left,height=720,down;long stick;String heading="RetroAchievements";JSONObject detail;boolean closed;
  static class Item{String title,sub,body,image;Runnable run;Item(String t,String s,String b,String i,Runnable r){title=t;sub=s;body=b;image=i;run=r;}}
  RommMarketplace(MainActivity a){super(a);this.a=a;ra=a.romm;setFocusableInTouchMode(true);ra.changed=()->{int selected=index,scroll=offset;build();index=Math.min(selected,Math.max(0,rows.size()-1));offset=scroll;invalidate();};home();}
  void add(String title,String sub,String body,String image,Runnable run){rows.add(new Item(title,sub,body,image,run));}
  void home(){screen=0;index=offset=0;build();invalidate();}
  void page(int n){screen=n;index=offset=0;build();invalidate();}
  String filter="",query="";JSONObject selectedGame;
  void build(){rows.clear();
    if(screen==0){heading="Game Marketplace";add("All Games",ra.games.length()+" games","Browse your personal RomM catalog.","",()->{filter="";query="";page(2);});add("Browse by Console","Platforms","Choose a console to browse its games.","",()->page(1));add("Search Games",query,"Search titles in your synced catalog.","",()->edit("Search Games",query,false,v->{query=v;filter="";page(2);}));add("Refresh Catalog",ra.busy?"Syncing…":"From your RomM server",ra.status,"",ra::refresh);add("Connection",ra.server().isEmpty()?"Set up RomM":ra.server(),"Connect to your own RomM server. Catalog browsing is read-only.","",()->page(4));}
    else if(screen==1){heading="Browse by Console";TreeMap<String,Integer> counts=new TreeMap<>(String.CASE_INSENSITIVE_ORDER);for(int i=0;i<ra.games.length();i++){String platform=RommClient.platform(ra.games.optJSONObject(i));counts.put(platform,counts.getOrDefault(platform,0)+1);}for(String platform:counts.keySet())add(platform,counts.get(platform)+" games","Browse your "+platform+" catalog.","",()->{filter=platform;query="";page(2);});if(rows.isEmpty())add("No consoles loaded","Refresh Catalog",ra.status,"",ra::refresh);}
    else if(screen==2){heading=query.isEmpty()?(filter.isEmpty()?"All Games":filter):"Search: "+query;ArrayList<JSONObject> list=new ArrayList<>();for(int i=0;i<ra.games.length();i++){JSONObject g=ra.games.optJSONObject(i);if(g!=null&&(filter.isEmpty()||filter.equals(RommClient.platform(g)))&&RommClient.title(g).toLowerCase(Locale.ROOT).contains(query.toLowerCase(Locale.ROOT)))list.add(g);}list.sort(Comparator.comparing(RommClient::title,String.CASE_INSENSITIVE_ORDER));for(JSONObject g:list)add(RommClient.title(g),RommClient.platform(g),description(g),RommClient.cover(g),()->{selectedGame=g;page(5);});if(rows.isEmpty())add(ra.games.length()==0?"No catalog loaded":"No matching games","",ra.status,"",()->page(4));}
    else if(screen==4){heading="RomM Connection";add("Server URL",ra.server().isEmpty()?"Not set":ra.server(),"Use your RomM base URL. HTTPS is recommended. HTTP is supported for private LAN IPs and .local hosts; credentials travel unencrypted over HTTP.","",()->edit("RomM Server URL",ra.server(),false,ra::server));add("Sign-in: "+(ra.basic()?"Username / Password":"API Token"),"Select to change","Choose a RomM client API token or your RomM username and password.","",ra::toggleAuth);if(ra.basic())add("Username",ra.username(),"Your RomM username.","",()->edit("RomM Username",ra.username(),false,ra::user));add(ra.basic()?"Password":"API Token",ra.prefs.contains("credential")?"Saved securely":"Not set","Stored encrypted on this device. Enter using the Blades keyboard.","",()->edit(ra.basic()?"RomM Password":"RomM API Token","",true,ra::credential));add("Paste Credential","From device clipboard","Read clipboard only when selected.","",this::pasteCredential);add("Connect / Refresh","",ra.status,"",ra::refresh);add("Disconnect","Remove saved connection and catalog","Does not change your server.","",()->page(6));}
    else if(screen==5&&selectedGame!=null){heading=RommClient.title(selectedGame);add(RommClient.title(selectedGame),RommClient.platform(selectedGame),description(selectedGame),RommClient.cover(selectedGame),()->{});add("File",selectedGame.optString("fs_name"),description(selectedGame),RommClient.cover(selectedGame),()->{});add("Back to Games","","Return to your catalog.","",()->page(2));}
    else if(screen==6){heading="Disconnect RomM?";add("Cancel","","Keep connection and catalog.","",()->page(4));add("Disconnect","","Remove this device's connection and cached catalog.","",()->{ra.disconnect();page(4);});}
  }
  String description(JSONObject g){String summary=g.optString("summary","");if(summary.equals("null")||summary.isEmpty())summary="No description supplied by your RomM server.";return RommClient.platform(g)+"\n\n"+summary;}
  void edit(String title,String initial,boolean secret,java.util.function.Consumer<String> save){boolean wasSecure=(a.getWindow().getAttributes().flags&WindowManager.LayoutParams.FLAG_SECURE)!=0;if(secret)a.getWindow().addFlags(WindowManager.LayoutParams.FLAG_SECURE);a.tools.editor=new BladesKeyboard(a,title,initial,secret?2048:256,false,v->{save.accept(v);build();invalidate();},()->{a.tools.editor=null;if(secret&&!wasSecure)a.getWindow().clearFlags(WindowManager.LayoutParams.FLAG_SECURE);post(this::requestFocus);});a.tools.editor.secret=secret;}
  void pasteCredential(){android.content.ClipboardManager cb=(android.content.ClipboardManager)a.getSystemService(Context.CLIPBOARD_SERVICE);ClipData clip=cb.getPrimaryClip();if(clip!=null&&clip.getItemCount()>0&&clip.getItemAt(0).getText()!=null)ra.credential(clip.getItemAt(0).getText().toString());else{ra.status="Clipboard does not contain credentials";invalidate();}}
  void back(){if(screen==0)close();else if(screen==5)page(2);else if(screen==6)page(4);else home();}
  void close(){closed=true;ra.changed=()->{};if(getParent() instanceof ViewGroup)((ViewGroup)getParent()).removeView(this);a.rommMarketplace=null;a.dashboard.requestFocus();}
  int slots(){return Math.max(3,Math.min(9,(int)((height-300)/61)));}
  void move(int n){index=Math.max(0,Math.min(rows.size()-1,index+n));if(index<offset)offset=index;if(index>=offset+slots())offset=index-slots()+1;invalidate();}
  void select(){if(index>=0&&index<rows.size())rows.get(index).run.run();invalidate();}
  @Override public boolean onKeyDown(int key,KeyEvent e){if(e.getRepeatCount()>0&&(key==96||key==97))return true;switch(key){case 19:move(-1);break;case 20:move(1);break;case 102:move(-slots());break;case 103:move(slots());break;case 96:case 66:case 23:select();break;case 97:case 4:back();break;case 99:page(4);break;case 100:ra.refresh();break;}return true;}
  @Override public boolean onKeyUp(int key,KeyEvent e){return true;}
  @Override public boolean onGenericMotionEvent(MotionEvent e){float y=e.getAxisValue(16);if(Math.abs(y)<.5f)y=e.getAxisValue(1);long now=android.os.SystemClock.uptimeMillis();if(Math.abs(y)<.5f){stick=0;return true;}if(now-stick>180){move(y>0?1:-1);stick=now;}return true;}
  void text(Canvas c,String s,float x,float y,float size,int color){p.setShader(null);p.setColor(color);p.setTypeface(a.dashboard.regular);p.setTextSize(size);c.drawText(s,x,y,p);}
  String fit(String s,float width,float size){p.setTypeface(a.dashboard.regular);p.setTextSize(size);if(p.measureText(s)<=width)return s;int n=s.length();while(n>0&&p.measureText(s.substring(0,n)+"…")>width)n--;return s.substring(0,n)+"…";}
  void gradient(Canvas c,RectF r,int top,int bottom,float radius){p.setShader(new LinearGradient(r.left,r.top,r.left,r.bottom,top,bottom,Shader.TileMode.CLAMP));c.drawRoundRect(r,radius,radius,p);p.setShader(null);}
  void button(Canvas c,float x,float y,String letter,String label,int color){p.setShader(new RadialGradient(x-4,y-5,17,new int[]{0xfff5f7de,color,0xff60543b},null,Shader.TileMode.CLAMP));c.drawCircle(x,y,15,p);p.setShader(null);text(c,letter,x-8,y+8,23,Color.WHITE);text(c,label,x+24,y+8,24,0xfffff9e9);}
  void wrapped(Canvas c,String s,float x,float y,float width,float size,float bottom){for(String paragraph:s.split("\n",-1)){String line="";for(String word:paragraph.split(" ")){p.setTextSize(size);if(p.measureText(line+" "+word)>width&&!line.isEmpty()){if(y>bottom)return;text(c,line,x,y,size,0xff3a3025);y+=size+6;line=word;}else line=line.isEmpty()?word:line+" "+word;}if(y>bottom)return;text(c,line,x,y,size,0xff3a3025);y+=size+6;}}
  @Override protected void onDraw(Canvas c){scale=Math.min(getWidth()/1280f,getHeight()/720f);height=getHeight()/scale;left=(getWidth()-1280*scale)/2;c.drawColor(0xff87908c);c.save();c.translate(left,0);c.scale(scale,scale);
    gradient(c,new RectF(88,0,1195,height),0xffb7783d,0xffeee0bf,0);
    for(int side=0;side<2;side++){c.save();if(side==1){c.translate(1280,0);c.scale(-1,1);}Path rail=new Path();rail.moveTo(0,0);rail.lineTo(92,0);rail.cubicTo(83,50,78,91,96,110);rail.cubicTo(112,125,104,height*.7f,90,height*.8f);rail.cubicTo(73,height*.9f,81,height*.96f,85,height);rail.lineTo(0,height);rail.close();c.clipPath(rail);p.setShader(new LinearGradient(0,0,110,0,new int[]{0xff465665,0xffe9eff5,0xff9baaba,0xffe3eaf0,0xff475665},null,Shader.TileMode.CLAMP));c.drawRect(0,0,120,height,p);p.setShader(null);c.restore();}
    c.save();c.translate(48,135);c.rotate(90);text(c,"marketplace",0,0,25,0xff27323d);c.restore();c.save();c.translate(1225,135);c.rotate(90);text(c,"xbox live",0,0,25,0xff27323d);c.restore();
    gradient(c,new RectF(100,-20,1180,96),0xff52351f,0xff9d6033,28);text(c,"Marketplace",128,60,38,0xfffaf3df);text(c,"RomM",1000,58,28,0xffe7d6b6);
    text(c,fit(heading,1000,30),130,145,30,0xff372b20);text(c,fit(ra.games.length()+" games · Your personal catalog",1000,22),130,181,22,0xff56402b);
    for(int i=offset;i<Math.min(rows.size(),offset+slots());i++){float y=215+(i-offset)*61;Item item=rows.get(i);if(i==index)gradient(c,new RectF(123,y-2,669,y+56),0xfffff6d4,0xffd5b77e,10);text(c,fit(item.title,500,25),140,y+25,25,0xff342c22);text(c,fit(item.sub,500,18),140,y+48,18,0xff66513a);p.setColor(0x55746345);c.drawLine(132,y+59,662,y+59,p);}
    if(offset>0)text(c,"▲",638,205,20,0xff675139);if(offset+slots()<rows.size())text(c,"▼",638,220+slots()*61,20,0xff675139);
    if(!rows.isEmpty()){Item item=rows.get(Math.min(index,rows.size()-1));gradient(c,new RectF(716,215,1146,height-130),0x99fff3d5,0x66cfb789,12);float bodyY=254;Bitmap art=ra.image(item.image);if(art!=null){float h=150,w=h*art.getWidth()/art.getHeight();if(w>300){w=300;h=w*art.getHeight()/art.getWidth();}p.setColor(Color.WHITE);c.drawBitmap(art,null,new RectF(748,240,748+w,240+h),p);bodyY=270+h;}wrapped(c,item.body,744,bodyY,370,24,height-150);}
    gradient(c,new RectF(100,height-104,1180,height+20),0xffc09b63,0xffe9d7ad,20);button(c,150,height-45,"A","Select",0xff7eaf3c);button(c,330,height-45,"B","Back",0xffbb4436);button(c,490,height-45,"Y","Refresh",0xffd2b747);button(c,710,height-45,"X","Connection",0xff368dc2);text(c,fit(ra.status,1000,18),135,height-78,18,0xff463722);c.restore();}
  @Override public boolean onTouchEvent(MotionEvent e){float x=(e.getX()-left)/scale,y=e.getY()/scale;if(e.getAction()==0){down=y;return true;}if(e.getAction()!=1)return true;if(Math.abs(y-down)>45){move(y<down?slots():-slots());return true;}if(y>height-65){if(x<290)select();else if(x<440)back();else if(x<680)ra.refresh();else page(4);return true;}if(x<110){back();return true;}if(x<680&&y>=215){int n=offset+(int)((y-215)/61);if(n<rows.size()&&n<offset+slots()){if(n==index)select();else{index=n;invalidate();}}}return true;}
}
